public int BinarySearch(int[] nums, int target)
{
    int left = 0;
    int right = nums.Length - 1;

    while (left <= right)
    {
        // Prevent integer overflow for large arrays
        int mid = left + (right - left) / 2;

        if (nums[mid] == target)
        {
            return mid;
        }
        else if (nums[mid] < target)
        {
            left = mid + 1; // target is in right half
        }
        else
        {
            right = mid - 1; // target is in left half
        }
    }

    return -1;
}

public int BinarySearchRecursive(int[] nums, int target)
{
    return SearchHelper(nums, target, 0, nums.Length - 1);
}

private int SearchHelper(int[] nums, int target, int left, int right)
{
    if (left > right) return -1;

    int mid = left + (right - left) / 2;

    if (nums[mid] == target)
    {
        return mid;
    }
    else if (nums[mid] < target)
    {
        return SearchHelper(nums, target, mid + 1, right);
    }
    else
    {
        return SearchHelper(nums, target, left, mid - 1);
    }
}

public int BinarySearchBuiltin(int[] nums, int target)
{
    int index = Array.BinarySearch(nums, target);
    return index >= 0 ? index : -1;
}
